    public void testNights() {
        LocalDate checkIn = LocalDate.of(2027, 7, 10);
        LocalDate checkOut = LocalDate.of(2027, 7, 12);

        int nights = PriceCalculator.calculateNights(checkIn, checkOut);
        assertEquals(2, nights);
    }
}

